INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 0, 'Bạn mới quen (新朋友)', '我叫马丁，是美国人。我在中国学习汉语，不学习法语。我的老师姓李，我们常常说“你好”、“您好”。我家有五口人：爸爸、妈妈、两个姐姐和我。今天我认识了一个新朋友，她叫朱云，是中国人。我们互相问好，认识她我很高兴。', 'Wǒ jiào Mǎdīng, shì Měiguó rén. Wǒ zài Zhōngguó xuéxí Hànyǔ, bù xuéxí Fǎyǔ. Wǒ de lǎoshī xìng Lǐ, wǒmen chángcháng shuō "nǐ hǎo", "nín hǎo". Wǒ jiā yǒu wǔ kǒu rén: bàba, māma, liǎng ge jiějie hé wǒ. Jīntiān wǒ rènshile yí ge xīn péngyou, tā jiào Zhūyún, shì Zhōngguó rén. Wǒmen hùxiāng wènhǎo, rènshi tā wǒ hěn gāoxìng.', 'Tôi tên là Martin, là người Mỹ. Tôi học tiếng Hán ở Trung Quốc, không học tiếng Pháp. Thầy giáo tôi họ Lý, chúng tôi thường nói "xin chào", "kính chào". Nhà tôi có năm người: bố, mẹ, hai chị gái và tôi. Hôm nay tôi quen được một người bạn mới, cô ấy tên Chu Vân, là người Trung Quốc. Chúng tôi chào hỏi nhau, quen được cô ấy tôi rất vui.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 0, 'Mã Đinh (马丁) là người nước nào?', ARRAY['美国 (Mỹ)','中国 (Trung Quốc)','法国 (Pháp)','日本 (Nhật Bản)'], 0, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 0, 'Ở Trung Quốc, Martin học môn gì?', ARRAY['法语 (tiếng Pháp)','英语 (tiếng Anh)','汉语 (tiếng Hán)','韩语 (tiếng Hàn)'], 2, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 0, 'Thầy giáo của Martin họ gì?', ARRAY['王 (Vương)','李 (Lý)','张 (Trương)','朱 (Chu)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 0, 'Nhà Martin có mấy người?', ARRAY['四口人 (bốn người)','五口人 (năm người)','六口人 (sáu người)','三口人 (ba người)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 0, '朱云 (Chu Vân) là ai đối với Martin?', ARRAY['老师 (giáo viên)','新朋友 (bạn mới)','姐姐 (chị gái)','妈妈 (mẹ)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 1, 'Một ngày cuối tuần (周末的一天)', '今天九月三号，星期五。阿明去市场买香蕉，两块五一斤，他买了三斤。然后他去中国银行，银行在学校前边，医院旁边。银行的人告诉他，这个星期天银行不开门。阿明说：“没关系，这个星期天我不忙，我想休息一下。”', 'Jīntiān jiǔyuè sān hào, xīngqīwǔ. Āmíng qù shìchǎng mǎi xiāngjiāo, liǎng kuài wǔ yì jīn, tā mǎile sān jīn. Ránhòu tā qù Zhōngguó Yínháng, yínháng zài xuéxiào qiánbian, yīyuàn pángbiān. Yínháng de rén gàosu tā, zhège xīngqītiān yínháng bù kāimén. Āmíng shuō: "Méi guānxi, zhège xīngqītiān wǒ bù máng, wǒ xiǎng xiūxi yíxià."', 'Hôm nay là ngày 3 tháng 9, thứ sáu. A Minh đi chợ mua chuối, hai đồng rưỡi một cân, anh mua ba cân. Sau đó anh đến Ngân hàng Trung Quốc, ngân hàng ở phía trước trường học, bên cạnh bệnh viện. Nhân viên ngân hàng nói với anh, chủ nhật này ngân hàng không mở cửa. A Minh nói: "Không sao, chủ nhật này tôi không bận, tôi muốn nghỉ ngơi một chút."');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 1, 'Hôm nay là ngày mấy?', ARRAY['九月三号 (3/9)','九月五号 (5/9)','八月三号 (3/8)','九月十号 (10/9)'], 0, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 1, 'Chuối A Minh mua giá bao nhiêu một cân?', ARRAY['三块 (3 đồng)','两块五 (2.5 đồng)','一块 (1 đồng)','五块 (5 đồng)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 1, 'Ngân hàng Trung Quốc ở đâu?', ARRAY['学校前边，医院旁边 (trước trường, cạnh bệnh viện)','食堂旁边 (cạnh căng tin)','图书馆里 (trong thư viện)','家里 (ở nhà)'], 0, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 1, 'Chủ nhật ngân hàng thế nào?', ARRAY['开门 (mở cửa)','不开门 (không mở cửa)','很忙 (rất bận)','没有人 (không có ai)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 1, 'Chủ nhật A Minh định làm gì?', ARRAY['去银行 (đi ngân hàng)','休息一下 (nghỉ ngơi)','去买香蕉 (đi mua chuối)','去学校 (đi học)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 2, 'Chuyển nhà và làm thêm (搬家和打工)', '崔浩已经搬家了，新房子很大，也很新。他每天在学校食堂吃饭，食堂的菜很好吃。上个星期，崔浩买了一件毛衣，颜色是红色的，他很喜欢。崔浩是大学生，他问老师：“大学生可以打工吗？”老师说：“可以，但是不能影响学习。”崔浩决定周末去公司打工，赚一点儿钱。', 'Cuī Hào yǐjīng bānjiā le, xīn fángzi hěn dà, yě hěn xīn. Tā měitiān zài xuéxiào shítáng chīfàn, shítáng de cài hěn hǎochī. Shàng ge xīngqī, Cuī Hào mǎile yí jiàn máoyī, yánsè shì hóngsè de, tā hěn xǐhuan. Cuī Hào shì dàxuéshēng, tā wèn lǎoshī: "Dàxuéshēng kěyǐ dǎgōng ma?" Lǎoshī shuō: "Kěyǐ, dànshì bù néng yǐngxiǎng xuéxí." Cuī Hào juédìng zhōumò qù gōngsī dǎgōng, zhuàn yìdiǎnr qián.', 'Thôi Hạo đã chuyển nhà rồi, nhà mới rất to, cũng rất mới. Mỗi ngày anh ăn cơm ở căng tin trường, món ăn ở căng tin rất ngon. Tuần trước, Thôi Hạo mua một cái áo len, màu đỏ, anh rất thích. Thôi Hạo là sinh viên đại học, anh hỏi thầy giáo: "Sinh viên đại học có thể đi làm thêm không?" Thầy giáo nói: "Có thể, nhưng không được ảnh hưởng việc học." Thôi Hạo quyết định cuối tuần đi làm thêm ở công ty, kiếm chút tiền.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 2, 'Nhà mới của Thôi Hạo thế nào?', ARRAY['很小很旧 (nhỏ và cũ)','很大很新 (to và mới)','很贵 (rất đắt)','没有房间 (không có phòng)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 2, 'Thôi Hạo ăn cơm ở đâu mỗi ngày?', ARRAY['家里 (ở nhà)','学校食堂 (căng tin trường)','餐厅 (nhà hàng)','银行 (ngân hàng)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 2, 'Cái áo len Thôi Hạo mua màu gì?', ARRAY['红色 (đỏ)','蓝色 (xanh dương)','白色 (trắng)','黑色 (đen)'], 0, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 2, 'Thầy giáo nói sinh viên đi làm thêm cần lưu ý gì?', ARRAY['不能赚钱 (không được kiếm tiền)','不能影响学习 (không được ảnh hưởng học tập)','不能去公司 (không được đến công ty)','不能周末打工 (không được làm cuối tuần)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 2, 'Thôi Hạo định đi làm thêm khi nào?', ARRAY['每天 (mỗi ngày)','周末 (cuối tuần)','上午 (buổi sáng)','从不 (không bao giờ)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 3, 'Món quà và Internet (礼物和上网)', '今天是马丁的生日，阿明想送他一件礼物，送蛋糕还是巧克力呢？朱云说她口语和听力都很好，但是阅读不太好，老师说多读书就能提高。崔浩昨天上了四个小时的网，眼睛很累，朋友们都叫他多休息。林娜家的暖气坏了，还没有修好，房间里很冷，她只好去图书馆学习。晚上，大家一起点了外卖，快餐可以送到家里，又方便又快。', 'Jīntiān shì Mǎdīng de shēngrì, Āmíng xiǎng sòng tā yí jiàn lǐwù, sòng dàngāo háishi qiǎokèlì ne? Zhūyún shuō tā kǒuyǔ hé tīnglì dōu hěn hǎo, dànshì yuèdú bú tài hǎo, lǎoshī shuō duō dúshū jiù néng tígāo. Cuī Hào zuótiān shàngle sì ge xiǎoshí de wǎng, yǎnjing hěn lèi, péngyoumen dōu jiào tā duō xiūxi. Línnà jiā de nuǎnqì huài le, hái méiyǒu xiūhǎo, fángjiān lǐ hěn lěng, tā zhǐhǎo qù túshūguǎn xuéxí. Wǎnshang, dàjiā yìqǐ diǎnle wàimài, kuàicān kěyǐ sòngdào jiā lǐ, yòu fāngbiàn yòu kuài.', 'Hôm nay là sinh nhật Martin, A Minh muốn tặng anh ấy một món quà, tặng bánh kem hay sô-cô-la đây? Chu Vân nói nói và nghe của cô đều tốt, nhưng đọc hiểu không tốt lắm, thầy giáo nói đọc sách nhiều sẽ tiến bộ. Thôi Hạo hôm qua lên mạng bốn tiếng, mắt rất mỏi, bạn bè đều bảo anh nghỉ ngơi nhiều hơn. Nhà Linna bị hỏng lò sưởi, vẫn chưa sửa xong, trong phòng rất lạnh, cô đành phải đi thư viện học. Buổi tối, mọi người cùng gọi đồ ăn giao hàng, đồ ăn nhanh có thể giao tận nhà, vừa tiện vừa nhanh.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 3, 'Hôm nay là sinh nhật của ai?', ARRAY['阿明 (A Minh)','马丁 (Martin)','崔浩 (Thôi Hạo)','林娜 (Linna)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 3, 'Kỹ năng nào của Chu Vân chưa tốt?', ARRAY['口语 (nói)','听力 (nghe)','阅读 (đọc hiểu)','写作 (viết)'], 2, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 3, 'Vì sao mắt Thôi Hạo rất mỏi?', ARRAY['看书 (đọc sách)','上网四个小时 (lên mạng 4 tiếng)','写作业 (làm bài tập)','看电视 (xem tivi)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 3, 'Vì sao Linna phải đi thư viện học?', ARRAY['家里没有网 (nhà không có mạng)','暖气坏了，房间很冷 (lò sưởi hỏng, phòng lạnh)','食堂关门了 (căng tin đóng cửa)','她喜欢图书馆 (cô thích thư viện)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 3, 'Buổi tối mọi người làm gì?', ARRAY['去银行 (đi ngân hàng)','点外卖 (gọi đồ ăn giao hàng)','去图书馆 (đi thư viện)','去买毛衣 (đi mua áo len)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 4, 'Đồ vật và cảm xúc (东西和心情)', '林娜把袋子放在桌子上了，袋子里有她的自行车钥匙，自行车是红色的，有点儿旧了。今年冬天变冷了，天气跟去年差不多冷。上星期，林娜的妈妈给她寄来了礼物，她很惊喜。可是，林娜有一个问题：她的中国朋友说话很快，她听不懂他们说的话。虽然她努力学习，但是有时候还是不太明白。', 'Línnà bǎ dàizi fàng zài zhuōzi shàng le, dàizi lǐ yǒu tā de zìxíngchē yàoshi, zìxíngchē shì hóngsè de, yǒudiǎnr jiù le. Jīnnián dōngtiān biàn lěng le, tiānqì gēn qùnián chàbuduō lěng. Shàng xīngqī, Línnà de māma gěi tā jìláile lǐwù, tā hěn jīngxǐ. Kěshì, Línnà yǒu yí ge wèntí: tā de Zhōngguó péngyou shuōhuà hěn kuài, tā tīng bu dǒng tāmen shuō de huà. Suīrán tā nǔlì xuéxí, dànshì yǒushíhou háishi bú tài míngbai.', 'Linna đã đặt túi lên bàn, trong túi có chìa khóa xe đạp của cô, xe đạp màu đỏ, hơi cũ rồi. Mùa đông năm nay lạnh hơn, thời tiết lạnh gần bằng năm ngoái. Tuần trước, mẹ Linna gửi quà cho cô, cô rất bất ngờ. Nhưng, Linna có một vấn đề: bạn Trung Quốc của cô nói rất nhanh, cô không hiểu họ nói gì. Mặc dù cô chăm chỉ học tập, nhưng đôi khi vẫn chưa hiểu rõ lắm.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 4, 'Linna đặt cái túi ở đâu?', ARRAY['桌子上 (trên bàn)','椅子上 (trên ghế)','床上 (trên giường)','地上 (dưới đất)'], 0, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 4, 'Xe đạp của Linna màu gì?', ARRAY['蓝色 (xanh dương)','红色 (đỏ)','白色 (trắng)','黑色 (đen)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 4, 'Thời tiết mùa đông năm nay thế nào?', ARRAY['比去年暖和 (ấm hơn năm ngoái)','跟去年差不多冷 (lạnh gần bằng năm ngoái)','一样暖和 (ấm như nhau)','没有变化 (không đổi)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 4, 'Ai gửi quà cho Linna?', ARRAY['老师 (giáo viên)','妈妈 (mẹ)','朋友 (bạn)','哥哥 (anh trai)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 4, 'Vấn đề của Linna là gì?', ARRAY['没有自行车 (không có xe đạp)','听不懂中国朋友说的话 (không hiểu bạn Trung Quốc nói)','没有钱 (không có tiền)','不喜欢冬天 (không thích mùa đông)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 5, 'Giáng sinh và Vạn Lý Trường Thành (圣诞节和长城)', '圣诞节快到了，大家都在准备礼物和卡片，气氛很热闹。晚上，山田正在看电视呢，节目里正在介绍长城。长城有八千八百五十多公里，是世界著名的历史古迹。山田很想去看看。上个星期，学校开了一个晚会，晚会开得非常成功，大家唱歌跳舞，非常开心。马丁说，他以前当过英语老师，那段经历有意思极了。', 'Shèngdànjié kuài dào le, dàjiā dōu zài zhǔnbèi lǐwù hé kǎpiàn, qìfēn hěn rènao. Wǎnshang, Shāntián zhèngzài kàn diànshì ne, jiémù lǐ zhèngzài jièshào Chángchéng. Chángchéng yǒu bāqiān bābǎi wǔshí duō gōnglǐ, shì shìjiè zhùmíng de lìshǐ gǔjì. Shāntián hěn xiǎng qù kànkan. Shàng ge xīngqī, xuéxiào kāile yí ge wǎnhuì, wǎnhuì kāi de fēicháng chénggōng, dàjiā chànggē tiàowǔ, fēicháng kāixīn. Mǎdīng shuō, tā yǐqián dāngguo Yīngyǔ lǎoshī, nà duàn jīnglì yǒuyìsi jíle.', 'Giáng sinh sắp đến, mọi người đều đang chuẩn bị quà và thiệp, không khí rất náo nhiệt. Buổi tối, Yamada đang xem tivi, chương trình đang giới thiệu về Vạn Lý Trường Thành. Trường Thành dài hơn 8850km, là di tích lịch sử nổi tiếng thế giới. Yamada rất muốn đi xem thử. Tuần trước, trường tổ chức một buổi tiệc, buổi tiệc rất thành công, mọi người hát và nhảy múa, rất vui vẻ. Martin nói, trước đây anh từng là giáo viên tiếng Anh, trải nghiệm đó cực kỳ thú vị.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 5, 'Sắp đến ngày lễ gì?', ARRAY['春节 (Tết)','圣诞节 (Giáng sinh)','国庆节 (Quốc khánh)','生日 (sinh nhật)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 5, 'Buổi tối Yamada đang làm gì?', ARRAY['看书 (đọc sách)','看电视 (xem tivi)','上网 (lên mạng)','睡觉 (ngủ)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 5, 'Trường Thành dài khoảng bao nhiêu?', ARRAY['八千八百五十多公里 (hơn 8850km)','五千公里 (5000km)','一万公里 (10000km)','三千公里 (3000km)'], 0, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 5, 'Buổi tiệc của trường thế nào?', ARRAY['不成功 (không thành công)','非常成功 (rất thành công)','很无聊 (rất nhàm chán)','没有人参加 (không ai tham gia)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 5, 'Trước đây Martin từng làm nghề gì?', ARRAY['医生 (bác sĩ)','英语老师 (giáo viên tiếng Anh)','记者 (nhà báo)','司机 (tài xế)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 6, 'Nhập gia tùy tục (入乡随俗)', '阿明第一次到中国的时候，常常迟到，后来他渐渐习惯了这里的生活，明白了“入乡随俗”的道理。他的中国朋友告诉他：儿子要回家的时候，妈妈会很激动。市场上有一个卖辣椒的女孩儿，她既聪明又勤劳，生意很好。林娜说，她和中国有个约会——这是她的梦想，她终于决定来中国留学。可是，为什么她第一天在餐厅要一个人站着吃饭呢？因为那天人太多，座位都满了，这也是这儿的习俗。', 'Āmíng dì-yī cì dào Zhōngguó de shíhou, chángcháng chídào, hòulái tā jiànjiàn xíguànle zhèlǐ de shēnghuó, míngbáile "rù xiāng suí sú" de dàolǐ. Tā de Zhōngguó péngyou gàosu tā: érzi yào huíjiā de shíhou, māma huì hěn jīdòng. Shìchǎng shàng yǒu yí ge mài làjiāo de nǚháir, tā jì cōngming yòu qínláo, shēngyi hěn hǎo. Línnà shuō, tā hé Zhōngguó yǒu ge yuēhuì — zhè shì tā de mèngxiǎng, tā zhōngyú juédìng lái Zhōngguó liúxué. Kěshì, wèishénme tā dì-yī tiān zài cāntīng yào yí ge rén zhànzhe chīfàn ne? Yīnwèi nà tiān rén tài duō, zuòwèi dōu mǎn le, zhè yě shì zhèr de xísú.', 'Lần đầu A Minh đến Trung Quốc, anh thường xuyên đến muộn, sau đó anh dần dần quen với cuộc sống ở đây, hiểu ra đạo lý "nhập gia tùy tục". Bạn Trung Quốc của anh nói với anh: khi con trai sắp về nhà, mẹ sẽ rất xúc động. Ở chợ có một cô gái bán ớt, cô vừa thông minh vừa chăm chỉ, buôn bán rất tốt. Linna nói, cô và Trung Quốc có một cuộc hẹn — đó là ước mơ của cô, cuối cùng cô quyết định đến Trung Quốc du học. Nhưng, vì sao ngày đầu tiên cô phải đứng ăn một mình ở nhà hàng? Vì hôm đó đông người quá, chỗ ngồi đầy hết rồi, đây cũng là phong tục ở đây.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 6, 'Lúc đầu đến Trung Quốc, A Minh thường bị gì?', ARRAY['迟到 (đến muộn)','生病 (ốm)','迷路 (lạc đường)','没有钱 (hết tiền)'], 0, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 6, '“入乡随俗” có nghĩa là gì trong bài?', ARRAY['随便生活 (sống tùy tiện)','到新地方要习惯当地的生活方式 (đến nơi mới phải quen với lối sống ở đó)','不用学习 (không cần học)','只说汉语 (chỉ nói tiếng Hán)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 6, 'Cô gái bán ớt ở chợ thế nào?', ARRAY['又懒又笨 (lười và ngốc)','既聪明又勤劳 (thông minh và chăm chỉ)','不喜欢工作 (không thích làm việc)','生意不好 (buôn bán không tốt)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 6, 'Ước mơ của Linna là gì?', ARRAY['当老师 (làm giáo viên)','和中国有个约会，来中国留学 (có hẹn với Trung Quốc, đến du học)','开餐厅 (mở nhà hàng)','学法语 (học tiếng Pháp)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 6, 'Vì sao Linna phải đứng ăn một mình?', ARRAY['她不喜欢坐 (cô không thích ngồi)','餐厅人太多，座位满了 (nhà hàng đông người, hết chỗ)','她来晚了 (cô đến muộn)','她在减肥 (cô đang giảm cân)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 7, 'Ước mơ và hạnh phúc (梦想和快乐)', '朱云说：“我这里一切都好，请放心。”她越来越适应这里的生活了。马丁要去埃及旅行，他一直想去看金字塔，这是他的旅行计划。老师给大家讲了一个旧梦的故事：一个人回到故乡，发现这里的变化比他想的还大。爱的教育比严格的教育更有效，老师对学生特别有耐心。其实，快乐真的很简单——学会知足，珍惜现在拥有的一切，就会更快乐。', 'Zhūyún shuō: "Wǒ zhèlǐ yíqiè dōu hǎo, qǐng fàngxīn." Tā yuè lái yuè shìyìng zhèlǐ de shēnghuó le. Mǎdīng yào qù Āijí lǚxíng, tā yìzhí xiǎng qù kàn jīnzìtǎ, zhè shì tā de lǚxíng jìhuà. Lǎoshī gěi dàjiā jiǎngle yí ge jiùmèng de gùshi: yí ge rén huídào gùxiāng, fāxiàn zhèlǐ de biànhuà bǐ tā xiǎng de hái dà. Ài de jiàoyù bǐ yángé de jiàoyù gèng yǒuxiào, lǎoshī duì xuésheng tèbié yǒu nàixīn. Qíshí, kuàilè zhēn de hěn jiǎndān — xuéhuì zhīzú, zhēnxī xiànzài yōngyǒu de yíqiè, jiù huì gèng kuàilè.', 'Chu Vân nói: "Ở đây con mọi thứ đều tốt, mẹ yên tâm." Cô càng ngày càng thích nghi với cuộc sống ở đây. Martin sẽ đi du lịch Ai Cập, anh luôn muốn đi xem kim tự tháp, đây là kế hoạch du lịch của anh. Thầy giáo kể cho mọi người một câu chuyện về giấc mơ cũ: một người trở về quê hương, phát hiện sự thay đổi ở đây lớn hơn anh nghĩ. Giáo dục bằng tình yêu thương hiệu quả hơn giáo dục nghiêm khắc, thầy cô rất kiên nhẫn với học sinh. Thực ra, hạnh phúc thực sự rất đơn giản — học cách biết đủ, trân trọng mọi thứ đang có, sẽ hạnh phúc hơn.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 7, 'Chu Vân nói gì về cuộc sống hiện tại?', ARRAY['一切都不好 (mọi thứ đều không tốt)','一切都好，越来越适应 (mọi thứ đều tốt, ngày càng thích nghi)','很想家 (rất nhớ nhà)','不习惯 (không quen)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 7, 'Martin muốn đi đâu du lịch?', ARRAY['中国 (Trung Quốc)','埃及 (Ai Cập)','越南 (Việt Nam)','法国 (Pháp)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 7, 'Trong câu chuyện, người trở về quê hương phát hiện điều gì?', ARRAY['什么都没变 (không có gì thay đổi)','变化比想的还大 (thay đổi lớn hơn nghĩ)','家乡变小了 (quê hương nhỏ lại)','没有人认识他 (không ai nhận ra anh)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 7, 'Theo bài, giáo dục kiểu nào hiệu quả hơn?', ARRAY['严格的教育 (nghiêm khắc)','爱的教育 (tình yêu thương)','没有教育 (không giáo dục)','考试教育 (thi cử)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 7, 'Theo bài, làm sao để hạnh phúc hơn?', ARRAY['赚更多钱 (kiếm nhiều tiền hơn)','学会知足，珍惜拥有的 (biết đủ, trân trọng những gì có)','买更多东西 (mua nhiều đồ hơn)','永远不满足 (không bao giờ hài lòng)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 8, 'Những câu chuyện nhỏ (小故事)', '书本里的蚂蚁：一只小蚂蚁在书页上爬来爬去，一个学生好奇地仔细观察它，发现小小的蚂蚁也有它自己的世界。是“枕头”，不是“针头”：一位外国学生发音不清楚，把“枕头”说成了“针头”，闹了一个大笑话。中国来信改变了我的生活：一位学生说，除了学习汉语，她还通过写信了解了中国文化。第一次打的：路上堵车，但是幸好司机走的路线很安全。飞回来的信鸽：这只鸽子飞了很远的距离才回来，真是一个奇迹。', 'Shūběn lǐ de mǎyǐ: yì zhī xiǎo mǎyǐ zài shūyè shang pá lái pá qù, yí ge xuésheng hàoqí de zǐxì guānchá tā, fāxiàn xiǎoxiǎo de mǎyǐ yě yǒu tā zìjǐ de shìjiè. Shì "zhěntou", bú shì "zhēntóu": yí wèi wàiguó xuésheng fāyīn bù qīngchu, bǎ "zhěntou" shuōchéngle "zhēntóu", nàole yí ge dà xiàohua. Zhōngguó láixìn gǎibiànle wǒ de shēnghuó: yí wèi xuésheng shuō, chúle xuéxí Hànyǔ, tā hái tōngguò xiěxìn liǎojiěle Zhōngguó wénhuà. Dì-yī cì dǎdī: lùshang dǔchē, dànshì xìnghǎo sījī zǒu de lùxiàn hěn ānquán. Fēi huílái de xìngē: zhè zhī gēzi fēile hěn yuǎn de jùlí cái huílái, zhēnshi yí ge qíjì.', 'Con kiến trong sách: một con kiến nhỏ bò tới bò lui trên trang sách, một học sinh tò mò quan sát nó thật kỹ, phát hiện con kiến bé nhỏ cũng có thế giới riêng của nó. Là "gối", không phải "đầu kim": một học sinh nước ngoài phát âm không rõ, nói nhầm "gối" thành "đầu kim", gây ra một trận cười lớn. Lá thư từ Trung Quốc thay đổi cuộc đời tôi: một học sinh nói, ngoài học tiếng Hán, cô còn hiểu thêm văn hóa Trung Quốc qua việc viết thư. Lần đầu đi taxi: trên đường tắc xe, nhưng may mà tuyến đường tài xế đi rất an toàn. Chim bồ câu đưa thư bay về: con chim bồ câu này bay một quãng đường rất xa mới về được, thật là một kỳ tích.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 8, 'Học sinh phát hiện điều gì khi quan sát con kiến?', ARRAY['它很危险 (nó nguy hiểm)','它也有自己的世界 (nó cũng có thế giới riêng)','它是害虫 (nó là sâu bọ)','它不会动 (nó không di chuyển)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 8, 'Học sinh nước ngoài đã nói nhầm từ nào?', ARRAY['枕头说成针头 (gối thành đầu kim)','老师说成学生 (giáo viên thành học sinh)','苹果说成香蕉 (táo thành chuối)','天气说成天气 (không nhầm)'], 0, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 8, 'Ngoài học tiếng Hán, cô học sinh còn học được gì qua viết thư?', ARRAY['数学 (toán)','中国文化 (văn hóa Trung Quốc)','英语 (tiếng Anh)','音乐 (âm nhạc)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 8, 'Vì sao chuyến taxi đầu tiên vẫn an toàn dù tắc đường?', ARRAY['司机走的路线很安全 (tài xế đi tuyến đường an toàn)','路上没有车 (đường không có xe)','他没有堵车 (anh không bị tắc)','他走路去了 (anh đi bộ)'], 0, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 8, 'Điều gì đặc biệt ở con chim bồ câu?', ARRAY['它不会飞 (nó không biết bay)','飞很远的距离才回来 (bay rất xa mới về được)','它迷路了 (nó bị lạc)','它不认识路 (nó không biết đường)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 9, 'Hẹn hò và kết bạn (约会和交友)', '崔浩每次都很准时，因为他把表拨快了三分钟，这样就不会迟到了。林娜和阿明约好六点见面，尽管阿明因为堵车迟到了，林娜还是等了他。有一位盲人朋友，即使看不见电影画面，他也能靠声音“看”电影，想象出情节。山田有一个中国笔友，他们经常写信交流，只有坚持写信，才能保持这段珍贵的友谊。老师告诉大家，每个人都应该受到尊重，千万不要小看自己，这就是“第一人格”。', 'Cuī Hào měicì dōu hěn zhǔnshí, yīnwèi tā bǎ biǎo bō kuàile sān fēnzhōng, zhèyàng jiù bú huì chídào le. Línnà hé Āmíng yuēhǎo liù diǎn jiànmiàn, jǐnguǎn Āmíng yīnwèi dǔchē chídào le, Línnà háishi děngle tā. Yǒu yí wèi mángrén péngyou, jíshǐ kàn bu jiàn diànyǐng huàmiàn, tā yě néng kào shēngyīn "kàn" diànyǐng, xiǎngxiàng chū qíngjié. Shāntián yǒu yí ge Zhōngguó bǐyǒu, tāmen jīngcháng xiěxìn jiāoliú, zhǐyǒu jiānchí xiěxìn, cái néng bǎochí zhè duàn zhēnguì de yǒuyì. Lǎoshī gàosu dàjiā, měi ge rén dōu yīnggāi shòudào zūnzhòng, qiānwàn búyào xiǎokàn zìjǐ, zhè jiùshì "dì-yī réngé".', 'Thôi Hạo lần nào cũng rất đúng giờ, vì anh vặn đồng hồ nhanh lên ba phút, như vậy sẽ không bị muộn. Linna và A Minh hẹn gặp nhau lúc sáu giờ, dù A Minh vì tắc đường mà đến muộn, Linna vẫn đợi anh. Có một người bạn khiếm thị, dù không nhìn thấy hình ảnh trên phim, anh vẫn có thể "xem" phim bằng âm thanh, tưởng tượng ra tình tiết. Yamada có một người bạn qua thư ở Trung Quốc, họ thường xuyên viết thư trao đổi, chỉ có kiên trì viết thư mới giữ được tình bạn quý báu này. Thầy giáo nói với mọi người, mỗi người đều nên được tôn trọng, nhất định đừng xem thường bản thân, đó chính là "nhân cách bậc nhất".');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 9, 'Vì sao Thôi Hạo luôn đúng giờ?', ARRAY['他起得很早 (anh dậy sớm)','他把表拨快了三分钟 (anh vặn đồng hồ nhanh 3 phút)','他住得很近 (anh ở gần)','他不用上课 (anh không phải học)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 9, 'Vì sao A Minh đến muộn buổi hẹn?', ARRAY['他忘记了 (anh quên)','堵车 (tắc đường)','他不想来 (anh không muốn đến)','他生病了 (anh bị ốm)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 9, 'Người bạn khiếm thị "xem" phim bằng cách nào?', ARRAY['用手摸 (dùng tay sờ)','靠声音想象情节 (dựa vào âm thanh tưởng tượng)','请人讲解 (nhờ người kể lại)','看字幕 (đọc phụ đề)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 9, 'Làm sao Yamada giữ được tình bạn với người bạn qua thư?', ARRAY['经常打电话 (thường gọi điện)','坚持写信交流 (kiên trì viết thư trao đổi)','每年见一次面 (mỗi năm gặp một lần)','送很多礼物 (tặng nhiều quà)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 9, '“第一人格” trong bài muốn nói điều gì?', ARRAY['要考第一名 (phải đứng nhất lớp)','每个人都应该受到尊重 (mỗi người đều nên được tôn trọng)','要做最聪明的人 (phải là người thông minh nhất)','不需要朋友 (không cần bạn bè)'], 1, 4);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 10, 'Kiên trì và trải nghiệm (坚持和经历)', '愚公决心把门前的大山移走，不管别人怎么笑话他，他都不放弃，因为他相信子孙后代能把山移走，坚持不懈才能成功。现在很方便，只要有一张公交卡，就能上车，不必带很多现金。我一直坚持“低碳生活”：骑车上班，垃圾分类，减少浪费。有一对父子一起爬长城，哪怕很累，父亲也坚持陪儿子爬到了最高处，感到很骄傲。还有一个年轻人决定搭车去柏林，路上遇到了很多善良的陌生人，这是一次难忘的冒险经历。', 'Yúgōng juéxīn bǎ ménqián de dàshān yízǒu, bùguǎn biéren zěnme xiàohua tā, tā dōu bú fàngqì, yīnwèi tā xiāngxìn zǐsūn hòudài néng bǎ shān yízǒu, jiānchí búxiè cái néng chénggōng. Xiànzài hěn fāngbiàn, zhǐyào yǒu yì zhāng gōngjiāokǎ, jiù néng shàngchē, búbì dài hěn duō xiànjīn. Wǒ yìzhí jiānchí "dītàn shēnghuó": qíchē shàngbān, lājī fēnlèi, jiǎnshǎo làngfèi. Yǒu yí duì fùzǐ yìqǐ pá Chángchéng, nǎpà hěn lèi, fùqīn yě jiānchí péi érzi pádàole zuì gāo chù, gǎndào hěn jiāo''ào. Hái yǒu yí ge niánqīngrén juédìng dāchē qù Bólín, lùshang yùdàole hěn duō shànliáng de mòshēngrén, zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Ngu Công quyết tâm dời quả núi lớn trước nhà đi, bất kể người khác cười nhạo thế nào, ông đều không từ bỏ, vì ông tin con cháu đời sau có thể dời được núi, kiên trì không ngừng mới có thể thành công. Bây giờ rất tiện, chỉ cần có một tấm thẻ xe buýt là có thể lên xe, không cần mang nhiều tiền mặt. Tôi luôn kiên trì lối sống "ít carbon": đi xe đạp đi làm, phân loại rác, giảm lãng phí. Có một cặp cha con cùng leo Trường Thành, dù rất mệt, người cha vẫn kiên trì đồng hành cùng con trai leo đến điểm cao nhất, cảm thấy rất tự hào. Còn có một chàng trai trẻ quyết định đi nhờ xe đến Berlin, trên đường gặp rất nhiều người lạ tốt bụng, đây là một trải nghiệm mạo hiểm khó quên.');
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 10, 'Vì sao Ngu Công không từ bỏ việc dời núi?', ARRAY['他很生气 (ông rất giận)','他相信子孙后代能把山移走 (ông tin con cháu có thể dời núi)','他没有别的事做 (ông không có việc gì khác)','邻居要求他这样做 (hàng xóm yêu cầu)'], 1, 0);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 10, 'Bây giờ đi xe buýt cần gì để không phải mang nhiều tiền mặt?', ARRAY['信用卡 (thẻ tín dụng)','公交卡 (thẻ xe buýt)','护照 (hộ chiếu)','身份证 (chứng minh thư)'], 1, 1);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 10, '“低碳生活” (cuộc sống ít carbon) trong bài gồm việc gì?', ARRAY['开车上班 (lái xe đi làm)','骑车、垃圾分类、减少浪费 (đi xe đạp, phân loại rác, giảm lãng phí)','多买东西 (mua nhiều đồ)','浪费水电 (lãng phí điện nước)'], 1, 2);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 10, 'Người cha trong câu chuyện leo Trường Thành đã làm gì?', ARRAY['半路放弃了 (bỏ cuộc giữa chừng)','坚持陪儿子爬到最高处 (kiên trì cùng con leo đến đỉnh)','让儿子自己爬 (để con tự leo)','没有去 (không đi)'], 1, 3);
INSERT INTO comprehension_questions (course_id, module_index, question, options, correct_index, order_index) VALUES (12, 10, 'Chàng trai đi nhờ xe đến Berlin đã gặp những ai trên đường?', ARRAY['很多坏人 (nhiều người xấu)','很多善良的陌生人 (nhiều người lạ tốt bụng)','没有人 (không ai)','他的家人 (người thân của anh)'], 1, 4);
